-- The source JSON is generated by the preceding fixed commerce query in the same task.
-- There is no cross-service application join or payload/recipient disclosure.
\set ON_ERROR_STOP on
WITH source AS (SELECT :'source'::jsonb AS body), expected AS (
    SELECT value::uuid AS id FROM source,
    jsonb_array_elements_text(source.body->'eventIds') value
)
SELECT (source.body - 'eventIds') || jsonb_build_object(
    'observedAt', clock_timestamp(),
    'notifications', (SELECT count(*) FROM domain.biz_notification notification
                      JOIN expected ON expected.id = notification.event_id
                      WHERE notification.notification_type = 'TeamExpired' AND notification.deleted = false),
    'consumedEvents', (SELECT count(*) FROM domain.sys_consumed_message consumed
                       JOIN expected ON expected.id = consumed.event_id WHERE consumed.consumer = 'notification'))
FROM source;
